public String capitalize(String s) {
    char[] c = s.toCharArray();
    boolean start = true;
    for (int i = 0; i < c.length; i++) {
        if (c[i] == ' ') {
            start = true;
        } else {
            if (start && c[i] >= 'a' && c[i] <= 'z') c[i] -= 32;
            start = false;
        }
    }
    return new String(c);
}

